// to fall down, the world's up projected onto the surface)
float3 HairStrand(float3 N) { float3 up = float3(0, 0, 1); float3 T = up - N * dot(N, up); float l = length(T); return l > 1e-3 ? T / l : float3(1, 0, 0); }
