	r += ambientSH[4].rgb * 1.092548 * n.x * n.y + ambientSH[5].rgb * 1.092548 * n.y * n.z;
	r += ambientSH[6].rgb * 0.315392 * (3.0 * n.z * n.z - 1.0);
	r += ambientSH[7].rgb * 1.092548 * n.x * n.z + ambientSH[8].rgb * 0.546274 * (n.x * n.x - n.y * n.y);
