	float e0, e1;
	float3 c = ProbeOne(i0, P, R, rough, e0);
	if (n > 1) {
		float3 c1 = ProbeOne(i1, P, R, rough, e1);
		c = lerp(c, c1, e0 / max(e0 + e1, 1e-3));
	}
	weight = saturate(2.0 - e0 / max(r0, 1.0));    // full inside the nearest probe's space, gone at twice its size
	return min(c, 64.0);
