	float2 suv = sc.xy * float2(0.5, -0.5) + 0.5;
	if (any(suv < 0) || any(suv > 1) || sc.z > 1) return 1;
	return Tex2DArray[indices1.x].SampleCmpLevelZero(sShadow, float3(suv, c), sc.z - shadowParams.y * 2);
