	float rmin = 1.0 / (min(abs(dir.x), abs(dir.y)) + red);
	dir = clamp(dir * rmin, -8.0, 8.0) * rcp;
	float3 a = 0.5 * (Tex2D[srcSrv].SampleLevel(sClamp, uv - dir / 6, 0).rgb + Tex2D[srcSrv].SampleLevel(sClamp, uv + dir / 6, 0).rgb);
